c.cpp:
class Solution {
public:
    int minimumDeletions(string s, int k) {
        int cnt[26] = {0};
        for (char c : s) cnt[c - 'a']++;
        vector<int> v;
        for (int i = 0; i < 26; i++) if (cnt[i]) v.push_back(cnt[i]);
        sort(v.rbegin(), v.rend());
        int ans = 0;
        for (int i = k; i < v.size(); i++) ans += v[i];
        return ans;
    }
};

c.java:
class Solution {
    public int minimumDeletions(String s, int k) {
        int[] cnt = new int[26];
        for (char c : s.toCharArray()) cnt[c - 'a']++;
        List<Integer> v = new ArrayList<>();
        for (int x : cnt) if (x > 0) v.add(x);
        v.sort(Collections.reverseOrder());
        int ans = 0;
        for (int i = k; i < v.size(); i++) ans += v.get(i);
        return ans;
    }
}

