var minimumDeletions = function(s, k) {
    const cnt = new Array(26).fill(0);
    for (const c of s) cnt[c.charCodeAt(0) - 97]++;
    const v = cnt.filter(x => x > 0).sort((a, b) => b - a);
    return v.slice(k).reduce((a, b) => a + b, 0);
};
